import { mkdir, rename, rm } from "node:fs/promises";
import { dirname, join, resolve } from "node:path";

export interface StoredObject {
  sizeBytes: number;
  sha256: string;
}

export class StoreError extends Error {
  constructor(public readonly code: "too_large" | "invalid_key") {
    super(code);
  }
}

/**
 * Where private bytes live. Keys are generated by the API and never accepted
 * from a client, so an adapter only has to keep them opaque and school-prefixed.
 */
export interface FileStore {
  write(
    key: string,
    body: ReadableStream<Uint8Array>,
    limit: number,
  ): Promise<StoredObject>;
  /** The object's bytes, or only those from `start` to `end` inclusive. */
  open(
    key: string,
    range?: { start: number; end: number },
  ): Promise<ReadableStream<Uint8Array> | null>;
  /** Whether an object is stored under the key, without reading it. */
  has(key: string): Promise<boolean>;
  move(from: string, to: string): Promise<void>;
  remove(key: string): Promise<void>;
  /**
   * Everything under a folder: a video's streams, which the media service
   * wrote, or the parts of an upload.
   */
  removeFolder(folder: string): Promise<void>;
}

/** A file waiting, ready or held, or one part of an upload on its way. */
const PRIVATE_KEY =
  /^t\/[0-9a-f-]{36}\/(?:[qfh]\/[0-9a-f-]{36}|u\/[0-9a-f-]{36}\/\d{1,4})$/;
/**
 * A video's stream folder (playlists, segments, poster and thumbnails) or
 * the folder an upload's parts wait in.
 */
const FOLDER = /^t\/[0-9a-f-]{36}\/[uv]\/[0-9a-f-]{36}$/;
/** Objects in the public-media bucket, under a published file's public key. */
export const PUBLIC_KEY = /^p\/[a-z0-9]{26}\/[A-Za-z0-9._-]{1,120}$/;

export class DiskFileStore implements FileStore {
  private readonly root: string;
  private readonly keys: RegExp;

  constructor(root: string, keys: RegExp = PRIVATE_KEY) {
    this.root = resolve(root);
    this.keys = keys;
  }

  private path(key: string) {
    if (!this.keys.test(key)) throw new StoreError("invalid_key");
    return join(this.root, key);
  }

  async write(
    key: string,
    body: ReadableStream<Uint8Array>,
    limit: number,
  ): Promise<StoredObject> {
    const path = this.path(key);
    await mkdir(dirname(path), { recursive: true });
    const sink = Bun.file(path).writer();
    const hasher = new Bun.CryptoHasher("sha256");
    let sizeBytes = 0;
    try {
      for await (const chunk of body) {
        sizeBytes += chunk.byteLength;
        if (sizeBytes > limit) throw new StoreError("too_large");
        hasher.update(chunk);
        await sink.write(chunk);
      }
      await sink.end();
    } catch (error) {
      await sink.end();
      await rm(path, { force: true });
      throw error;
    }
    return { sizeBytes, sha256: hasher.digest("hex") };
  }

  async open(key: string, range?: { start: number; end: number }) {
    const file = Bun.file(this.path(key));
    if (!(await file.exists())) return null;
    return range
      ? file.slice(range.start, range.end + 1).stream()
      : file.stream();
  }

  has(key: string) {
    return Bun.file(this.path(key)).exists();
  }

  async move(from: string, to: string) {
    const target = this.path(to);
    await mkdir(dirname(target), { recursive: true });
    await rename(this.path(from), target);
  }

  async remove(key: string) {
    await rm(this.path(key), { force: true });
  }

  async removeFolder(folder: string) {
    if (!FOLDER.test(folder)) throw new StoreError("invalid_key");
    await rm(join(this.root, folder), { recursive: true, force: true });
  }
}

/**
 * The endpoint a bucket's client is given. In the virtual-hosted style the
 * bucket is the first label of the host, and Bun's client then takes the
 * endpoint as the bucket's own address and ignores its bucket option.
 */
export function bucketEndpoint(
  endpoint: string | undefined,
  bucket: string | undefined,
  style: "path" | "virtual",
): string | undefined {
  if (style === "path" || endpoint === undefined || bucket === undefined)
    return endpoint;
  const url = new URL(endpoint);
  url.hostname = `${bucket}.${url.hostname}`;
  return url.href.replace(/\/$/, "");
}

/**
 * Objects in an S3-compatible bucket (S3, R2, MinIO and the like). The
 * protocol has no rename, so a move is a copy followed by a delete.
 */
export class S3FileStore implements FileStore {
  private readonly client: Bun.S3Client;
  private readonly keys: RegExp;

  constructor(client: Bun.S3Client, keys: RegExp = PRIVATE_KEY) {
    this.client = client;
    this.keys = keys;
  }

  private object(key: string) {
    if (!this.keys.test(key)) throw new StoreError("invalid_key");
    return this.client.file(key);
  }

  async write(
    key: string,
    body: ReadableStream<Uint8Array>,
    limit: number,
  ): Promise<StoredObject> {
    const object = this.object(key);
    const sink = object.writer();
    const hasher = new Bun.CryptoHasher("sha256");
    let sizeBytes = 0;
    try {
      for await (const chunk of body) {
        sizeBytes += chunk.byteLength;
        if (sizeBytes > limit) throw new StoreError("too_large");
        hasher.update(chunk);
        await sink.write(chunk);
      }
      await sink.end();
    } catch (error) {
      await Promise.resolve(
        sink.end(error instanceof Error ? error : undefined),
      ).catch(() => undefined);
      await object.delete().catch(() => undefined);
      throw error;
    }
    return { sizeBytes, sha256: hasher.digest("hex") };
  }

  async open(key: string, range?: { start: number; end: number }) {
    const object = this.object(key);
    if (!(await object.exists())) return null;
    return range
      ? object.slice(range.start, range.end + 1).stream()
      : object.stream();
  }

  has(key: string) {
    return this.object(key).exists();
  }

  async move(from: string, to: string) {
    const source = this.object(from);
    await this.object(to).write(source);
    await source.delete();
  }

  async remove(key: string) {
    await this.object(key).delete();
  }

  async removeFolder(folder: string) {
    if (!FOLDER.test(folder)) throw new StoreError("invalid_key");
    // A bucket has no folders: the objects under the prefix go page by page.
    for (;;) {
      const page = await this.client.list({ prefix: `${folder}/` });
      const keys = (page.contents ?? []).map((object) => object.key);
      if (keys.length === 0) return;
      await Promise.all(keys.map((key) => this.client.delete(key)));
    }
  }
}

/** Up to `limit` leading bytes of a stored object, without reading the rest. */
export async function readPrefix(
  store: FileStore,
  key: string,
  limit: number,
): Promise<Uint8Array> {
  const body = await store.open(key);
  if (!body) return new Uint8Array(0);
  const reader = body.getReader();
  const parts: Uint8Array[] = [];
  let length = 0;
  try {
    while (length < limit) {
      const { done, value } = await reader.read();
      if (done) break;
      parts.push(value);
      length += value.byteLength;
    }
  } finally {
    await reader.cancel();
  }
  const bytes = new Uint8Array(Math.min(length, limit));
  let offset = 0;
  for (const part of parts) {
    const slice = part.subarray(0, bytes.length - offset);
    bytes.set(slice, offset);
    offset += slice.byteLength;
    if (offset >= bytes.length) break;
  }
  return bytes;
}
